declare(strict_types=1);
namespace OCA\Mcp\Tests\Unit\Modules\Mail;
use PHPUnit\Framework\TestCase;
final class MailPartBodyRoleTest extends TestCase {
    protected function setUp():void {parent::setUp();$path=dirname(__DIR__,5).'/native/mail-guard/src/Content/PartBodyRole.php';self::assertFileExists($path);require_once $path;}
    private function part(string $id,?string $parent,string $mime,?string $cid=null,?string $start=null,?string $type=null):array {return ['part_id'=>$id,'parent_id'=>$parent,'mime_type'=>$mime,'content_id'=>$cid,'disposition'=>null,'filename'=>null,'advertised_size'=>2097152,'leaf'=>!str_starts_with($mime,'multipart/'),'related_start'=>$start,'related_type'=>$type];}
    public function testDefaultRelatedRootKeepsItsCidBodyAndExcludesSecondaryText():void {$parts=\OCA\Mail\Content\PartBodyRole::classify([$this->part('0',null,'multipart/related',type:'text/html'),$this->part('1','0','text/html','primary@test'),$this->part('2','0','text/plain','resource@test')]);self::assertSame(['container','body','attachment'],array_column($parts,'role'));self::assertSame('1',$parts[0]['related_root_id']);}
    public function testExplicitRelatedStartCanSelectNonfirstCidBody():void {$parts=\OCA\Mail\Content\PartBodyRole::classify([$this->part('0',null,'multipart/related',start:'<primary@test>',type:'text/html'),$this->part('1','0','text/plain','resource@test'),$this->part('2','0','text/html','primary@test')]);self::assertSame(['container','attachment','body'],array_column($parts,'role'));self::assertSame('2',$parts[0]['related_root_id']);}
    public function testNestedAlternativeWithinRelatedRootKeepsBothBodiesOnly():void {$parts=\OCA\Mail\Content\PartBodyRole::classify([$this->part('0',null,'multipart/related',type:'multipart/alternative'),$this->part('1','0','multipart/alternative'),$this->part('1.1','1','text/plain'),$this->part('1.2','1','text/html','primary@test'),$this->part('2','0','text/plain','resource@test')]);self::assertSame(['container','container','body','body','attachment'],array_column($parts,'role'));}
    public function testSinglePrimaryCidDoesNotMakeAnAttachment():void {$parts=\OCA\Mail\Content\PartBodyRole::classify([$this->part('1',null,'text/plain','primary@test')]);self::assertSame('body',$parts[0]['role']);self::assertNull($parts[0]['related_root_id']);}
    public function testAmbiguousOrContradictoryRelatedSelectionRefuses():void {foreach(['missing','duplicate','type','malformed'] as $case){$parts=[$this->part('0',null,'multipart/related',start:$case==='malformed'?'primary@test':($case==='missing'?'<missing@test>':'<primary@test>'),type:$case==='type'?'text/plain':'text/html'),$this->part('1','0','text/html','primary@test'),$this->part('2','0','text/plain',$case==='duplicate'?'primary@test':'resource@test')];$refused=false;try{\OCA\Mail\Content\PartBodyRole::classify($parts);}catch(\RuntimeException){$refused=true;}self::assertTrue($refused,$case);}}
    public function testAttachmentAdapterUsesSharedRolesInsteadOfCidHeuristic():void {
        $parts=\OCA\Mail\Content\PartBodyRole::classify([$this->part('0',null,'multipart/related',type:'text/html'),$this->part('1','0','text/html','primary@test'),$this->part('2','0','text/plain','resource@test')]);
        $reader=$this->createMock(\OCA\Mcp\Modules\Mail\Integration\MailContentReader::class);$reader->method('available')->willReturn(true);$reader->method('listParts')->willReturn(['parts'=>$parts]);$reader->expects(self::never())->method('readAttachment');
        $access=new \OCA\Mcp\Modules\Mail\Attachments\MailAttachmentAccess($this->createMock(\OCA\Mcp\Modules\Mail\Integration\MailMessageLocator::class),$this->createMock(\OCA\Mcp\Modules\Mail\Integration\MailServices::class),content:$reader);$rows=$access->list('alice',7);self::assertSame(['2'],array_column($rows,'id'));self::assertFalse($rows[0]['size_verified']);
    }
    public function testAttachmentReadAndSaveUseClosedAttachmentApiWithTheirOwnOrigins():void {
        $origins=[];$reader=$this->createMock(\OCA\Mcp\Modules\Mail\Integration\MailContentReader::class);$reader->method('available')->willReturn(true);$reader->expects(self::exactly(2))->method('readAttachment')->willReturnCallback(static function(string $uid,int $message,string $part,string $tool='mail_read_attachment')use(&$origins):array {$origins[]=$tool;self::assertSame('alice',$uid);self::assertSame(7,$message);self::assertSame('2',$part);self::assertContains($tool,['mail_read_attachment','mail_save_attachment']);return ['bytes'=>'abc','byte_count'=>3,'sha256'=>hash('sha256','abc'),'part_id'=>'2','filename'=>null,'mime_type'=>'text/plain'];});
        $access=new \OCA\Mcp\Modules\Mail\Attachments\MailAttachmentAccess($this->createMock(\OCA\Mcp\Modules\Mail\Integration\MailMessageLocator::class),$this->createMock(\OCA\Mcp\Modules\Mail\Integration\MailServices::class),content:$reader);self::assertSame('YWJj',$access->read('alice',7,'2')['content_base64']);self::assertSame('abc',$access->readForSave('alice',7,'2')['bytes']);self::assertSame(['mail_read_attachment','mail_save_attachment'],$origins);
    }
}
